import{verifyPaceToolbarRelease,readBeforePaceToolbar}from'./check-pace-toolbar-release-20261101.mjs';
import assert from 'node:assert/strict';import{readFileSync}from'node:fs';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
const base='d829bf9b4dea365c8197b977f5e38ddca9062adf',live='d829bf9b4dea365c8197b977f5e38ddca9062adf',folder='docs/photo-choice-fit-20261101/';
const git=(...a)=>execFileSync('git',a,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),sort=a=>a.sort((a,b)=>a.localeCompare(b)),lines=b=>b.toString().trim().split('\n').filter(Boolean);
const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
export function verifyPhotoChoiceFitRelease(read=readFileSync){
 const successor=verifyPaceToolbarRelease(read),currentRead=read;read=file=>readBeforePaceToolbar(file,successor,currentRead);
 const r=JSON.parse(read('docs/klink-owner-release-photo-choice-fit-20261101.json'));assert.equal(r.approvedBy,'Nico');assert.equal(r.publicationApproved,true);assert.equal(r.appearanceChangeApproved,true);assert.equal(r.baselineSourceCommit,base);assert.equal(r.liveSourceCommit,live);assert(r.userRequest.includes('luister en kies een foto')&&r.userRequest.includes('scrollen'));
 git('merge-base','--is-ancestor',live,base);git('merge-base','--is-ancestor',base,'HEAD');
 const changed=sort(lines(git('diff','--name-only',base,successor.baselineSourceCommit,'--',...roots)));assert.deepEqual(changed,sort([...r.changedFiles,'docs/appearance-floor-20261031/floor.json',r.approval]));assert.deepEqual(sort(Object.keys(r.files)),r.changedFiles);for(const f of r.changedFiles)assert.equal(sha(read(f)),r.files[f],f);
 assert.equal(git('diff','--name-only',base,successor.baselineSourceCommit,'--','components','hooks','data','lib','public','db','drizzle','.github','package.json','package-lock.json','wrangler.jsonc').length,0,'No player logic, content, audio, progress, routes or dependencies change');
 const before=git('show',base+':app/learner-layout.css').toString(),actual=read('app/learner-layout.css').toString();assert(actual.startsWith(before));const delta=actual.slice(before.length);assert.equal(sha(Buffer.from(delta)),r.cssDeltaSha256);assert(delta.includes('flex: 1 1 0')&&delta.includes('@media (max-height: 700px)'));assert(!delta.includes('font-size')&&!delta.includes('object-fit: cover'),'No smaller letters or cropped photos');
 const floor=JSON.parse(read('docs/appearance-floor-20261031/floor.json')),old=JSON.parse(git('show',base+':docs/appearance-floor-20261031/floor.json'));assert.deepEqual({...floor,approvedUpdates:old.approvedUpdates},old);assert.deepEqual(floor.approvedUpdates,[...old.approvedUpdates,r.approval]);const approval=JSON.parse(read(r.approval));assert.equal(approval.userRequest,r.userRequest);assert.deepEqual(approval.files,r.files);
 const browser=JSON.parse(read(folder+'checks.json'));assert.equal(browser.checks.length,500);assert.equal(browser.native.length,2);assert.deepEqual(browser.errors,[]);for(const c of browser.checks)for(const k of['stageFits','allChoicesFit','allPhotosFit','footerFits','noHorizontalScroll','oldProgressPreserved'])assert.equal(c[k],true,k);assert(browser.native.every(c=>c.nativePlayback&&c.enter&&c.arrows&&c.touch&&c.progressPreserved));
 const review=JSON.parse(read(folder+'review.json'));for(const k of['all119Rounds','fullPhotos','touchTargets48','contentPreserved','audioPreserved','progressPreserved','keyboard','mobile','localOnly'])assert.equal(review[k],true,k);
 const backup=JSON.parse(read(folder+'backup.json'));assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);return {...r,successor};
}
export function readBeforePhotoChoiceFit(file,r,read=readFileSync){return r.changedFiles.includes(file)||file==='docs/appearance-floor-20261031/floor.json'?git('show',base+':'+file):readBeforePaceToolbar(file,r.successor,read);}
